import{_ as a,o as i,c as n,a2 as s}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Cooking","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/professions/cooking.md","filePath":"es/game-design/professions/cooking.md"}'),o={name:"es/game-design/professions/cooking.md"};function r(t,e,l,c,d,p){return i(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="cooking" tabindex="-1">Cooking <a class="header-anchor" href="#cooking" aria-label="Enlace permanente a &quot;Cooking&quot;">​</a></h1><p><strong>Estado del diseño:</strong> Propuesto; todas las mecánicas, ejemplos y caminos técnicos siguientes siguen siendo candidatos. <strong>Implementación:</strong> este lote documental no establece ninguna implementación del rediseño. <strong>Disponibilidad:</strong> no establecida. <strong>Verificación:</strong> solo revisión documental; sin prueba de juego. <strong>Revisado:</strong> 2026-10-09 para la versión pública; se conservan el estado del diseño y las mecánicas de la especificación canónica.</p><p><a href="/Syrolands-Public/es/guide/professions/cooking.html">Resumen para jugadores</a> · <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Sistema de profesiones</a></p><h2 id="purpose-and-profession-loop" tabindex="-1">Propósito y ciclo profesional <a class="header-anchor" href="#purpose-and-profession-loop" aria-label="Enlace permanente a &quot;Propósito y ciclo profesional&quot;">​</a></h2><p>Cooking debería ser una actividad física en el mundo, no un menú de recetas.</p><h3 id="stations" tabindex="-1">Puestos de trabajo <a class="header-anchor" href="#stations" aria-label="Enlace permanente a &quot;Puestos de trabajo&quot;">​</a></h3><ul><li>puesto de cocina silvestre alrededor de una hoguera (mediante Camping);</li><li>cocina/fogón/horno/parrilla en casas, posadas y tabernas;</li><li>posibles campamentos más completos con mayor Camping.</li></ul><h3 id="station-interface" tabindex="-1">Interfaz del puesto <a class="header-anchor" href="#station-interface" aria-label="Enlace permanente a &quot;Interfaz del puesto&quot;">​</a></h3><ul><li>representa el puesto;</li><li>arrastrar/soltar ingredientes desde la mochila;</li><li>zonas como olla, parrilla y mesa de preparación;</li><li>el ingrediente empieza a cocinarse inmediatamente al colocarlo.</li></ul><p>Los ingredientes tienen estados/intervalos de cocción, por ejemplo:</p><ul><li>crudo;</li><li>poco hecho;</li><li>al punto;</li><li>bien hecho;</li><li>quemado;</li></ul><p>o estados equivalentes específicos de cada ingrediente.</p><p>Distintos ingredientes tienen distintas progresiones de tiempo/estado.</p><p>La habilidad debería ampliar tolerancias y mejorar el control sin automatizar toda la destreza.</p><p>Posible abstracción térmica:</p><ul><li>Baja</li><li>Media</li><li>Alta</li><li>Muy alta</li></ul><p>La calidad del combustible/fuego puede conectar con Camping/Lumberjacking sin exigir una simulación excesiva.</p><h3 id="recipes" tabindex="-1">Recetas <a class="header-anchor" href="#recipes" aria-label="Enlace permanente a &quot;Recetas&quot;">​</a></h3><ul><li>pueden requerir varios ingredientes en estados de preparación específicos;</li><li>el montaje final ocurre en una zona de preparación/montaje;</li><li>las recetas pueden descubrirse mediante exploración, libros, cocineros, culturas, misiones, ruinas y experimentación.</li></ul><p>La calidad de la receta puede depender de:</p><ul><li>calidad de ingredientes;</li><li>estado/tiempo de cocción;</li><li>habilidad;</li><li>puesto;</li><li>ejecución.</li></ul><p>La comida no debería convertirse simplemente en mejoras de estadísticas similares a pociones. Preferir efectos relacionados con:</p><ul><li>saciedad;</li><li>nutrición;</li><li>recuperación;</li><li>eficiencia de stamina;</li><li>fatiga;</li><li>resistencia a la temperatura;</li><li>concentración/recuperación;</li><li>beneficios situacionales de supervivencia.</li></ul><h3 id="taste-codex-personal-taste" tabindex="-1">Taste Codex / gusto personal <a class="header-anchor" href="#taste-codex-personal-taste" aria-label="Enlace permanente a &quot;Taste Codex / gusto personal&quot;">​</a></h3><ul><li>cada personaje puede descubrir preferencias alimentarias personales al comer;</li><li>las preferencias no deberían mostrarse por completo al crear el personaje;</li><li>descubrir un plato/familia favoritos puede producir efectos de satisfacción/bienestar especialmente altos;</li><li>esto incentiva probar nuevos alimentos;</li><li>los chefs se benefician del conocimiento culinario amplio y de completar su diario culinario.</li></ul><p>Esto puede convertirse en una meta avanzada de la profesión.</p><h2 id="knowledge-and-specialization" tabindex="-1">Conocimiento y especialización <a class="header-anchor" href="#knowledge-and-specialization" aria-label="Enlace permanente a &quot;Conocimiento y especialización&quot;">​</a></h2><p><strong>Culinary Journal / Taste Codex.</strong> Estilos culinarios, recetas y conocimiento alimentario regional; un diario amplio y dominar la preparación pueden sostener el juego culinario avanzado.</p><h2 id="shared-progression-production-and-economy" tabindex="-1">Progresión, producción y economía compartidas <a class="header-anchor" href="#shared-progression-production-and-economy" aria-label="Enlace permanente a &quot;Progresión, producción y economía compartidas&quot;">​</a></h2><p>El <a href="/Syrolands-Public/es/game-design/characters/skills-and-skillcap.html">marco de habilidades del personaje</a> define la enseñanza y la dirección de límites/aumentos. El <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Sistema de profesiones</a> define descubrimiento artesanal, intercambio de conocimiento, maestría manual, producción por lotes, encargos y reputación multidimensional. Aquí no se redefinen esas reglas de forma independiente. La <a href="/Syrolands-Public/es/game-design/items/itemization-and-craft-quality.html">especificación de calidad</a> define el rango compartido de resultados y las propiedades raras de objetos.</p><h2 id="related-skills-and-field-interactions" tabindex="-1">Habilidades relacionadas e interacciones en expediciones <a class="header-anchor" href="#related-skills-and-field-interactions" aria-label="Enlace permanente a &quot;Habilidades relacionadas e interacciones en expediciones&quot;">​</a></h2><p>Camping aporta fuego/puestos de campo; Lumberjacking informa sobre combustibles; la recuperación por comida puede cruzarse con Healing y el sistema propuesto de Meditation/Concentration. Efectos exactos y acumulación siguen sin resolverse.</p><p><a href="/Syrolands-Public/es/game-design/professions/alchemy.html">Alchemy</a> · <a href="/Syrolands-Public/es/game-design/professions/lumberjacking.html">Lumberjacking</a> · <a href="/Syrolands-Public/es/game-design/living-world.html#knowledge-professions-and-traces">Camping y conocimiento del mundo</a> · <a href="/Syrolands-Public/es/game-design/magic.html#meditation-and-concentration">Meditation y Concentration</a>.</p><h2 id="abstraction-and-technical-boundary" tabindex="-1">Abstracción y límite técnico <a class="header-anchor" href="#abstraction-and-technical-boundary" aria-label="Enlace permanente a &quot;Abstracción y límite técnico&quot;">​</a></h2><p>Conservar únicamente estados y respuestas que sustenten decisiones significativas. Se aplican las <a href="/Syrolands-Public/es/game-design/professions/profession-system.html#performance-abstraction-and-authority">restricciones compartidas de abstracción/autoridad</a> y la arquitectura del mundo vivo; la persistencia requiere un diseño técnico separado. Nada de esto selecciona ID de paquetes, esquemas, temporizadores, recursos de interfaz ni algoritmos de ejecución.</p><h2 id="open-questions" tabindex="-1">Preguntas abiertas <a class="header-anchor" href="#open-questions" aria-label="Enlace permanente a &quot;Preguntas abiertas&quot;">​</a></h2><p>Intervalos de cocción y precisión de respuesta; acceso a puestos y propiedad de ingredientes; fallo de receta/montaje; abstracción de combustible/calor; descubrimiento de gustos, persistencia y límites de satisfacción; recuperación frente a medicina y acumulación con pociones. No se establece una fórmula nutricional ni una mejora gratuita de combate.</p><p>El <a href="/Syrolands-Public/es/game-design/professions/profession-system.html#open-questions-and-reconciliation-required">registro compartido de conciliación</a> define los conflictos entre sistemas. Los experimentos y evidencias existentes de combate no validan este rediseño profesional.</p>',38)])])}const g=a(o,[["render",r]]);export{m as __pageData,g as default};
